import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;
        int test_cases = 1;
        for (int i = 0; i < test_cases; ++i) {
            process(br);
        }
    }

    public static void process(BufferedReader br) throws IOException {
        StringTokenizer st = new StringTokenizer(br.readLine());
        int total = Integer.parseInt(st.nextToken());
        int threshold = Integer.parseInt(st.nextToken());
        double[] probabilities = new double[total];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < total; ++i) {
            probabilities[i] = Double.parseDouble(st.nextToken());
        }
        StringBuilder output = new StringBuilder();
        for (int i = 0; i < total; ++i) {
            if (Math.abs(probabilities[i]) < 1e-6) {
                output.append("0 ");
                continue;
            }
            int subset_size = total - 1;
            int size = 1 << subset_size;
            double[] dp = new double[size];
            double[] p = new double[subset_size];
            int index = 0;
            for (int j = 0; j < total; ++j) {
                if (j != i) {
                    p[index++] = probabilities[j];
                }
            }
            dp[0] = probabilities[i];
            double result = dp[0];
            for (int mask = 1; mask < size; ++mask) {
                double sumP = 0.0, sum = 0.0;
                int count = 0;
                for (int t = 0; t < subset_size; ++t) {
                    if ((mask & (1 << t)) != 0) {
                        sumP += p[t];
                        sum += p[t] * dp[mask ^ (1 << t)];
                        ++count;
                    }
                }
                dp[mask] = sum / (1 - sumP);
                if (count < threshold) {
                    result += dp[mask];
                }
            }
            output.append(result).append(" ");
        }
        System.out.println(output.toString().trim());
    }
}
